mapper.select:
select a.plan_id, a.plan_code, a.device_id, a.up_region_id, a.robot_id, a.plan_name, a.type, b.dict_note AS plan_type_name, a.plan_point_types, a.create_time, a.update_time from t_cruise_plan a LEFT JOIN t_dict_business b ON a.type = b.dict_code where 1 = 1
and 1 = 2
AND a.plan_code = #{planCode, jdbcType=VARCHAR}

select
a.plan_id,
a.plan_code,
a.device_id,
a.up_region_id,
a.robot_id,
a.plan_name,
a.type,
a.plan_point_types,
a.create_time,
a.update_time
from t_cruise_plan a
JOIN t_dict_business b ON a.type = b.dict_code AND b.col_name = "plan_type"
where 1 = 1
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.plan_code = #{planCode, jdbcType=VARCHAR}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.plan_name = #{planName, jdbcType=VARCHAR}
 and a.type = #{type, jdbcType=INTEGER}
 and a.plan_point_types = #{planPointTypes, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}

select
a.plan_id,
a.plan_code,
a.device_id,
a.up_region_id,
a.robot_id,
a.plan_name,
a.type,
a.plan_point_types,
(select count(*) from t_cruise_plan_attr b where b.plan_id = a.plan_id) as total,
a.create_time,
a.update_time
from t_cruise_plan a
JOIN t_dict_business b ON a.type = b.dict_code AND b.col_name = "plan_type"
where 1 = 1
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.plan_code = #{planCode, jdbcType=VARCHAR}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.plan_name like concat('%',#{planName, jdbcType=VARCHAR},'%') 
 and a.type = #{type, jdbcType=INTEGER}
 and a.plan_point_types = #{planPointTypes, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 order by a.create_time desc

select
a.plan_id,
a.plan_code,
a.device_id,
a.up_region_id,
a.robot_id,
a.plan_name,
a.type,
b.dict_note AS type_name,
a.plan_point_types,
(select count(*) from u_patrol_plan_attr b where b.plan_id = a.plan_id) as total,
a.create_time,
a.update_time
from t_cruise_plan a
JOIN t_dict_business b ON a.type = b.dict_code AND b.col_name = "plan_type"
where 1 = 1
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.plan_code = #{planCode, jdbcType=VARCHAR}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.plan_name like concat('%',#{planName, jdbcType=VARCHAR},'%') 
 and a.type = #{type, jdbcType=INTEGER}
 and a.plan_point_types = #{planPointTypes, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
order by a.create_time desc

SELECT a.device_id, a.instance_id, a.device_mete_id, a.station_id, a.custom_id, a.station_name, a.cruise_id, a.cruise_name, b.device_name,k.dict_note AS custom_name, (CASE WHEN ISNULL(j.mete_name) AND ISNULL(d.inspection_name) AND ISNULL(f.preset_name) THEN '' WHEN ISNULL(j.mete_name) AND ISNULL(d.inspection_name) THEN f.preset_name WHEN ISNULL(j.mete_name) AND ISNULL(f.preset_name) THEN d.inspection_name WHEN ISNULL(d.inspection_name) AND ISNULL(f.preset_name) THEN j.mete_name WHEN ISNULL(d.inspection_name) THEN CONCAT(j.mete_name,'/',f.preset_name) WHEN ISNULL(f.preset_name) THEN CONCAT(j.mete_name,'/',d.inspection_name) END) AS instance_name,e.robot_name, g.camera_name,h.camera_name AS inferad_name,i.dict_note AS cruise_type_name,a.identify_type FROM t_cruise_point_instance a LEFT JOIN t_std_device b ON a.device_id = b.device_id LEFT JOIN t_cruise_point_attr c ON a.instance_id = c.instance_id LEFT JOIN t_robot_inspection d ON d.inspection_id = a.cruise_id LEFT JOIN t_robot_info e ON d.robot_id = e.robot_id LEFT JOIN t_camera_preset f ON a.cruise_id = f.preset_id LEFT JOIN t_camera_info g ON f.preset_id = g.camera_name AND g.camera_type = 205 LEFT JOIN t_camera_info h ON f.preset_id = h.camera_name AND h.camera_type = 206 LEFT JOIN t_dict_business i ON i.dict_code = a.cruise_type AND i.col_name = "cruise_type" LEFT JOIN t_std_devicemete j ON j.device_mete_id = a.device_mete_id LEFT JOIN t_dict_business k ON k.dict_code = j.custom_id AND k.col_name = "custom_type" where 1 = 1 AND a.device_id IN
#{deviceId, jdbcType=BIGINT}
and j.inspection_type = 1 GROUP BY a.instance_id ORDER BY a.instance_id asc,a.device_id, a.custom_id

SELECT a.device_id, a.instance_id, a.device_mete_id, a.station_id, a.custom_id, a.station_name, a.cruise_id, a.cruise_name, b.device_name,k.dict_note AS custom_name, (CASE WHEN ISNULL(j.mete_name) AND ISNULL(d.inspection_name) AND ISNULL(f.preset_name) THEN '' WHEN ISNULL(j.mete_name) AND ISNULL(d.inspection_name) THEN f.preset_name WHEN ISNULL(j.mete_name) AND ISNULL(f.preset_name) THEN d.inspection_name WHEN ISNULL(d.inspection_name) AND ISNULL(f.preset_name) THEN j.mete_name WHEN ISNULL(d.inspection_name) THEN CONCAT(j.mete_name,'/',f.preset_name) WHEN ISNULL(f.preset_name) THEN CONCAT(j.mete_name,'/',d.inspection_name) END) AS instance_name,e.robot_name, g.camera_name,h.camera_name AS inferad_name,i.dict_note AS cruise_type_name,a.identify_type FROM t_cruise_point_instance a LEFT JOIN t_std_device b ON a.device_id = b.device_id LEFT JOIN t_cruise_point_attr c ON a.instance_id = c.instance_id LEFT JOIN t_robot_inspection d ON d.inspection_id = a.cruise_id LEFT JOIN t_robot_info e ON d.robot_id = e.robot_id LEFT JOIN t_camera_preset f ON a.cruise_id = f.preset_id LEFT JOIN t_camera_info g ON f.preset_id = g.camera_name AND g.camera_type = 205 LEFT JOIN t_camera_info h ON f.preset_id = h.camera_name AND h.camera_type = 206 LEFT JOIN t_dict_business i ON i.dict_code = a.cruise_type AND i.col_name = "cruise_type" LEFT JOIN t_std_devicemete j ON j.device_mete_id = a.device_mete_id LEFT JOIN t_dict_business k ON k.dict_code = b.custom_id AND k.col_name = "custom_type" where 1 = 1
and a.device_id = #{deviceId, jdbcType=VARCHAR}
and d.robot_id = #{robotId, jdbcType=BIGINT}
and d.main_operation_type = #{type, jdbcType=BIGINT}
and j.inspection_type =2 GROUP BY a.instance_id ORDER BY a.instance_id asc,a.device_id, a.custom_id
